type FieldMap = Record<string, SelectionSetNode | undefined>

/**
 * Collects the fields directly selected within a selection set, resolving any
 * inline fragments and fragment spreads into their constituent fields.
 */
function collectFields(
  selectionSet: SelectionSetNode | undefined,
  info: GraphQLResolveInfo
): FieldMap {
  const fields: FieldMap = {}
  if (!selectionSet) return fields

  for (const selection of selectionSet.selections) {
    switch (selection.kind) {
      case Kind.FIELD: {
        const field = selection as FieldNode
        fields[field.name.value] = field.selectionSet
        break
      }
      case Kind.INLINE_FRAGMENT: {
        const fragment = selection as InlineFragmentNode
        Object.assign(fields, collectFields(fragment.selectionSet, info))
        break
      }
      case Kind.FRAGMENT_SPREAD: {
        const spread = selection as FragmentSpreadNode
        const fragment = info.fragments[spread.name.value]
        if (fragment) {
          Object.assign(fields, collectFields(fragment.selectionSet, info))
        }
        break
      }
    }
  }

  return fields
}

/**
 * Returns the names of the fields requested on the nodes of a collection field.
 *
 * Handles both the `nodes { ... }` and `edges { node { ... } }` selection
 * shapes.
 */
export function requestedNodeFieldNames(info: GraphQLResolveInfo): Array<string> {
  const topSelectionSet = info.fieldNodes[0]?.selectionSet
  const topFields = collectFields(topSelectionSet, info)

  let nodeSelectionSet = topFields.nodes
  if (!nodeSelectionSet && topFields.edges) {
    const edgeFields = collectFields(topFields.edges, info)
    nodeSelectionSet = edgeFields.node
  }

  return Object.keys(collectFields(nodeSelectionSet, info))
}
