import { Result } from '~/features/helpers.fn'
import { POST } from './app/api/graphql/route'

function post(query: string, variables?: Record<string, unknown>) {
  const request = new Request('http://localhost/api/graphql', {
    method: 'POST',
    body: JSON.stringify({ query, variables }),
  })
  return POST(request).then((r) => r.json())
}

describe('searchDocs', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    vi.spyOn(console, 'error').mockImplementation(() => {})
    createContentEmbedding.mockResolvedValue(Result.ok([0.1, 0.2, 0.3]))
    rpc.mockResolvedValue({
      data: [
        {
          id: 1,
          page_title: 'Getting Started',
          type: 'markdown',
          href: '/docs/getting-started',
          content: 'full content here',
          subsections: [],
        },
      ],
      error: null,
    })
  })

  it('returns nodes with title/href and maps page_title', async () => {
    const json = await post(`query { searchDocs(query: "auth") { nodes { title href } } }`)
    expect(json.errors).toBeUndefined()
    expect(json.data.searchDocs.nodes[0]).toEqual({
      title: 'Getting Started',
      href: '/docs/getting-started',
    })
    // content not requested -> include_full_content false
    expect(rpc).toHaveBeenCalledWith('search_content', {
      embedding: [0.1, 0.2, 0.3],
      include_full_content: false,
      max_result: undefined,
    })
  })

  it('includes content and passes include_full_content true + max_result when requested', async () => {
    const json = await post(`query { searchDocs(query: "auth", limit: 5) { nodes { title content } } }`)
    expect(json.errors).toBeUndefined()
    expect(json.data.searchDocs.nodes[0].content).toBe('full content here')
    expect(rpc).toHaveBeenCalledWith('search_content', {
      embedding: [0.1, 0.2, 0.3],
      include_full_content: true,
      max_result: 5,
    })
  })

  it('returns a required validation error when query omitted', async () => {
    const json = await post(`query { searchDocs { nodes { title } } }`)
    expect(json.errors[0].message).toContain('required')
  })

  it('returns Internal Server Error when embedding fails', async () => {
    const { ApiError } = await import('~/app/api/utils')
    createContentEmbedding.mockResolvedValue(Result.error(new ApiError('boom')))
    const json = await post(`query { searchDocs(query: "auth") { nodes { title } } }`)
    expect(json.errors[0].message).toBe('Internal Server Error')
  })
})
